parameters.functionCode:
// Validate incoming payload from CS Pulse playbook orchestrator
const body = $input.first().json.body || $input.first().json;

// Expected payload structure from CS Pulse:
// {
//   action_id: string,
//   playbook_id: string,
//   customer_id: number,
//   customer_name: string,
//   action_type: 'create_jira_issue',
//   parameters: {
//     summary: string,
//     description: string,
//     issue_type: string,
//     priority: string,
//     labels: string[],
//     custom_fields: object
//   },
//   callback_url: string,
//   triggered_by: string,
//   triggered_at: string
// }

const required = ['action_id', 'playbook_id', 'customer_id', 'parameters'];
const missing = required.filter(f => !body[f]);

if (missing.length > 0) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

const params = body.parameters || {};

return [{
  json: {
    action_id: body.action_id,
    playbook_id: body.playbook_id,
    customer_id: body.customer_id,
    customer_name: body.customer_name || `Customer ${body.customer_id}`,
    callback_url: body.callback_url || `${process.env.CS_PULSE_URL || '{{CS_PULSE_URL}}'}/api/webhooks/playbook-callback`,
    summary: params.summary || `[CS Pulse] Action required for ${body.customer_name || body.customer_id}`,
    description: params.description || 'Action triggered by CS Pulse playbook.',
    issue_type: params.issue_type || 'Task',
    priority: params.priority || 'Medium',
    labels: params.labels || ['cs-pulse', 'playbook-action'],
    custom_fields: params.custom_fields || {},
    triggered_by: body.triggered_by || 'system',
    triggered_at: body.triggered_at || new Date().toISOString()
  }
}];

