parameters.functionCode:
// Prepare success callback payload
const jiraResponse = $input.first().json;
const originalData = $('Validate Payload').first().json;

return [{
  json: {
    action_id: originalData.action_id,
    playbook_id: originalData.playbook_id,
    customer_id: originalData.customer_id,
    status: 'completed',
    result: {
      jira_issue_key: jiraResponse.key,
      jira_issue_id: jiraResponse.id,
      jira_issue_url: `${process.env.JIRA_BASE_URL || '{{JIRA_BASE_URL}}'}/browse/${jiraResponse.key}`,
      summary: jiraResponse.fields?.summary || originalData.summary
    },
    completed_at: new Date().toISOString()
  }
}];

// Prepare error callback payload
const error = $input.first();
const originalData = $('Validate Payload').first().json;

return [{
  json: {
    action_id: originalData.action_id,
    playbook_id: originalData.playbook_id,
    customer_id: originalData.customer_id,
    status: 'failed',
    error: {
      message: error.json?.message || 'Failed to create Jira issue',
      code: error.json?.statusCode || 'JIRA_CREATE_FAILED',
      details: error.json?.description || null
    },
    failed_at: new Date().toISOString()
  }
}];
